import React, { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import api from '../../api/axios';

export default function PageRelais() {
  const { user }  = useAuth();
  const [relais, setRelais]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [log, setLog]         = useState([]);

  useEffect(() => { fetchRelais(); }, []);

  const fetchRelais = () => {
    api.get('/relais').then(r => {
      setRelais(r.data);
      setLoading(false);
    });
  };

  const toggle = async (relai) => {
  const nouvelEtat = relai.etat === 1 ? 0 : 1;

  // ✅ 1. Mettre à jour l'UI IMMÉDIATEMENT (sans attendre le serveur)
  setRelais(prev => prev.map(r =>
    r.id === relai.id ? { ...r, etat: nouvelEtat } : r
  ));

  // ✅ 2. Ajouter au journal IMMÉDIATEMENT
  const now = new Date().toTimeString().slice(0, 8);
  setLog(prev => [{
    time:       now,
    nom:        relai.nom,
    machine:    relai.machine?.nom || relai.actionneur?.machine?.nom || '—',
    actionneur: relai.actionneur?.nom || null,
    etat:       nouvelEtat === 1 ? 'ON' : 'OFF',
  }, ...prev].slice(0, 30));

  // ✅ 3. Envoyer au serveur EN ARRIÈRE-PLAN
  try {
    await api.put(`/relais/${relai.id}`, {
      etat:           nouvelEtat,
      utilisateur_id: user?.id,
    });
  } catch(e) {
    // ❌ Si ça échoue → annuler le changement dans l'UI
    setRelais(prev => prev.map(r =>
      r.id === relai.id ? { ...r, etat: relai.etat } : r
    ));
    setLog(prev => prev.filter((_, i) => i !== 0));
    alert('Erreur — action annulée');
  }
};

  // Grouper par machine
  const parMachine = relais.reduce((acc, r) => {
    const machineName = r.machine?.nom || r.actionneur?.machine?.nom || 'Sans machine';
    if (!acc[machineName]) acc[machineName] = [];
    acc[machineName].push(r);
    return acc;
  }, {});

  const totalOn  = relais.filter(r => r.etat === 1).length;
  const totalOff = relais.filter(r => r.etat === 0).length;

  if (loading) return <div style={S.loading}>Chargement...</div>;

  return (
    <div>
      {/* Métriques */}
      <div style={S.metricsRow}>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#2ed573'}}/>
          <div style={S.mcardLabel}>RELAIS ACTIFS (ON)</div>
          <div style={S.mcardVal}>{totalOn}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#ff4757'}}/>
          <div style={S.mcardLabel}>RELAIS INACTIFS (OFF)</div>
          <div style={S.mcardVal}>{totalOff}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#0099ff'}}/>
          <div style={S.mcardLabel}>TOTAL RELAIS</div>
          <div style={S.mcardVal}>{relais.length}</div>
        </div>
      </div>

      <div style={S.grid2}>
        {/* Relais groupés par machine */}
        <div>
          {Object.entries(parMachine).map(([machineName, items]) => (
            <div key={machineName} style={S.card}>
              <div style={S.cardHead}>
                <span style={S.cardTitle}>{machineName}</span>
                <span style={S.cardSub}>{items.length} relai(s)</span>
              </div>
              {items.map(relai => (
                <div key={relai.id} style={S.relaiRow}>
                  <div style={{flex:1}}>
                    <div style={S.relaiNom}>{relai.nom}</div>
                    {/* Affiche l'actionneur associé si présent */}
                    {relai.actionneur?.nom && (
                      <div style={S.relaiActionneur}>
                        <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#7a8394" strokeWidth="2">
                          <circle cx="12" cy="12" r="3"/>
                          <path d="M12 1v4M12 19v4M4.22 4.22l2.83 2.83M16.95 16.95l2.83 2.83M1 12h4M19 12h4M4.22 19.78l2.83-2.83M16.95 7.05l2.83-2.83"/>
                        </svg>
                        <span>{relai.actionneur.nom}</span>
                        <span style={S.relaiActTypePill}>{relai.actionneur.type}</span>
                      </div>
                    )}
                    {relai.canal && (
                      <div style={S.relaiCanal}>{relai.canal}</div>
                    )}
                  </div>
                  <div style={S.toggleGroup}>
                    <span style={{
                      ...S.etatLabel,
                      color: relai.etat === 1 ? '#2ed573' : '#ff4757'
                    }}>
                      {relai.etat === 1 ? 'ON' : 'OFF'}
                    </span>
                    <div
                      style={{
                        ...S.toggle,
                        background: relai.etat === 1 ? '#2ed573' : 'rgba(255,255,255,0.1)',
                        cursor: user?.role === 'operateur' ? 'not-allowed' : 'pointer',
                        opacity: user?.role === 'operateur' ? 0.5 : 1,
                      }}
                      onClick={() => user?.role !== 'operateur' && toggle(relai)}
                    >
                      <div style={{
                        ...S.toggleThumb,
                        transform: relai.etat === 1 ? 'translateX(20px)' : 'translateX(2px)',
                      }}/>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ))}
        </div>

        {/* Journal */}
        <div style={S.card}>
          <div style={S.cardHead}>
            <span style={S.cardTitle}>JOURNAL DES ACTIONS</span>
            {log.length > 0 && (
              <button
                style={S.btnClear}
                onClick={() => setLog([])}
              >Effacer</button>
            )}
          </div>
          {log.length === 0 ? (
            <div style={S.empty}>Aucune action effectuée</div>
          ) : (
            log.map((entry, i) => (
              <div key={i} style={S.logRow}>
                {/* Heure */}
                <span style={S.logTime}>{entry.time}</span>

                <div style={{flex:1, minWidth:0}}>
                  {/* Machine */}
                  <div style={S.logMachine}>
                    <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#4a5260" strokeWidth="2">
                      <rect x="2" y="3" width="20" height="14" rx="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/>
                    </svg>
                    {entry.machine}
                  </div>
                  {/* Relais + actionneur */}
                  <div style={S.logRelais}>
                    {entry.actionneur && (
                      <span style={S.logActTag}>⚙ {entry.actionneur}</span>
                    )}
                    <span style={S.logNom}>{entry.nom}</span>
                  </div>
                </div>

                {/* État */}
                <span style={{
                  ...S.logEtat,
                  color:       entry.etat === 'ON' ? '#2ed573' : '#ff4757',
                  background:  entry.etat === 'ON' ? 'rgba(46,213,115,0.10)' : 'rgba(255,71,87,0.10)',
                  borderColor: entry.etat === 'ON' ? 'rgba(46,213,115,0.25)' : 'rgba(255,71,87,0.25)',
                }}>
                  {entry.etat}
                </span>
              </div>
            ))
          )}
        </div>
      </div>

      {user?.role === 'operateur' && (
        <div style={S.warning}>
          ⚠️ Vous n'avez pas les droits pour modifier les relais
        </div>
      )}
    </div>
  );
}

const S = {
  loading:         { color:'#7a8394', textAlign:'center', marginTop:40 },
  metricsRow:      { display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:14, marginBottom:20 },
  mcard:           { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'18px 20px', position:'relative', overflow:'hidden' },
  mcardBar:        { position:'absolute', top:0, left:0, right:0, height:2 },
  mcardLabel:      { fontSize:10, color:'#4a5260', letterSpacing:1.5, textTransform:'uppercase', marginBottom:12 },
  mcardVal:        { fontSize:28, fontWeight:600, color:'#e8eaf0' },
  grid2:           { display:'grid', gridTemplateColumns:'2fr 1fr', gap:16 },
  card:            { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'20px 22px', marginBottom:16 },
  cardHead:        { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16, paddingBottom:12, borderBottom:'1px solid rgba(255,255,255,0.05)' },
  cardTitle:       { fontSize:11, color:'#7a8394', letterSpacing:1, textTransform:'uppercase' },
  cardSub:         { fontSize:11, color:'#4a5260' },

  // Relais row
  relaiRow:        { display:'flex', alignItems:'center', gap:12, padding:'12px 0', borderBottom:'1px solid rgba(255,255,255,0.04)' },
  relaiNom:        { fontSize:13, color:'#e8eaf0', marginBottom:3, fontWeight:500 },
  relaiActionneur: { display:'flex', alignItems:'center', gap:5, fontSize:11, color:'#7a8394', marginBottom:2 },
  relaiActTypePill:{ fontSize:9, color:'#4a5260', background:'rgba(255,255,255,0.05)', borderRadius:3, padding:'1px 5px' },
  relaiCanal:      { fontSize:11, color:'#4a5260' },

  // Toggle
  toggleGroup:     { display:'flex', alignItems:'center', gap:10, flexShrink:0 },
  etatLabel:       { fontSize:11, fontWeight:600, width:28 },
  toggle:          { width:44, height:24, borderRadius:12, position:'relative', transition:'background 0.2s', flexShrink:0 },
  toggleThumb:     { position:'absolute', top:2, width:20, height:20, borderRadius:'50%', background:'white', transition:'transform 0.2s', boxShadow:'0 1px 3px rgba(0,0,0,0.3)' },

  // Journal
  logRow:          { display:'flex', alignItems:'center', gap:8, padding:'9px 0', borderBottom:'1px solid rgba(255,255,255,0.04)' },
  logTime:         { color:'#4a5260', fontSize:10, flexShrink:0, fontFamily:'monospace' },
  logMachine:      { display:'flex', alignItems:'center', gap:4, fontSize:10, color:'#4a5260', marginBottom:2 },
  logRelais:       { display:'flex', alignItems:'center', gap:6 },
  logActTag:       { fontSize:10, color:'#7a8394', background:'rgba(255,255,255,0.05)', borderRadius:4, padding:'1px 6px', flexShrink:0 },
  logNom:          { fontSize:11, color:'#e8eaf0', fontWeight:500 },
  logEtat:         { fontSize:10, fontWeight:700, flexShrink:0, padding:'2px 8px', borderRadius:4, border:'1px solid', letterSpacing:0.5 },
  btnClear:        { fontSize:10, color:'#4a5260', background:'transparent', border:'1px solid rgba(255,255,255,0.08)', borderRadius:5, padding:'3px 8px', cursor:'pointer' },
  empty:           { color:'#4a5260', fontSize:12, textAlign:'center', padding:'20px 0' },
  warning:         { marginTop:16, padding:'10px 16px', background:'rgba(245,166,35,0.08)', border:'1px solid rgba(245,166,35,0.20)', borderRadius:8, color:'#f5a623', fontSize:12 },
};
